"""Option bank for the Professional Cloud DevOps Engineer practice sets.

Every option label is an action or a named capability, so an item can ask what a
team should do without the distractor collapsing into a definition. Keys are
authoring identifiers only and never appear in an export.
"""

TERMS = {}


def t(key, label, meaning):
    if key in TERMS:
        raise ValueError(f"duplicate option key: {key}")
    TERMS[key] = (label, meaning)


